// CSV serializer for audit timeline rows
// build {{sim.sessionId}}
export function toCsv(rows: Record<string, string | number>[]): string {
  const cols = Object.keys(rows[0] ?? {});
  const esc = (v: string | number) => '"' + String(v).replaceAll('"', '""') + '"';
  return [cols.join(','), ...rows.map((r) => cols.map((c) => esc(r[c] ?? '')).join(','))].join('\n');
}

// Streamed CSV export
// build {{sim.sessionId}}
export async function* streamCsv(pages: AsyncIterable<string[]>): AsyncGenerator<string> {
  for await (const page of pages) yield page.join('\n') + '\n';
}

// Export button
// build {{sim.sessionId}}
export function ExportButton(props: { onExport: () => void }) {
  return <button type="button" onClick={props.onExport}>Export CSV</button>;
}
